import { useState, useEffect } from "react";
import api from "../api"; // التأكد من أن هذا الملف يرسل التوكن في الـ headers
import StudentLayout from "./StudentLayout";

// ── الخرائط اللونية للحالات القادمة من الـ Backend ──
const STATUS_MAP = {
  pending:  { label:"Pending",  badge:"badge-orange", dot:"bg-[#d4a84b]",  icon:"⏳", msg:"Awaiting company decision." },
  accepted: { label:"Accepted", badge:"badge-green",  dot:"bg-[#e8a09a]",icon:"✅", msg:"Your application was accepted! Agreement being prepared." },
  rejected: { label:"Rejected", badge:"badge-red",    dot:"bg-[#d4849a]",    icon:"❌", msg:"Your application was not selected this time." },
};

// ── مكون الخط الزمني (Timeline) ──
function Timeline({ status, date }) {
  // توليد الخط الزمني بناءً على حالة الطلب الحقيقية
  const steps = [
    { label: "Applied", date: date || "Recently", done: true },
    { label: "Profile reviewed", date: "In progress", done: status !== "pending" },
    { label: "Company decision", date: status === "pending" ? "—" : "Completed", done: status !== "pending" },
    { label: "Agreement generated", date: "—", done: status === "accepted" },
  ];

  return (
    <div>
      {steps.map((step, i) => {
        const isLast = i === steps.length - 1;
        const isRefused = status === "rejected" && i === 2;
        const isDone = step.done && !isRefused;
        return (
          <div key={i} className="flex gap-3">
            <div className="flex flex-col items-center">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 shrink-0 transition-all ${
                isRefused ? "bg-rose border-red-400 text-[#b5394e]"
                : isDone  ? "bg-[#2E7DF7] border-[#2E7DF7] text-white"
                :           "bg-white border-slate-200 text-slate-300"
              }`}>
                {isRefused ? "✕" : isDone ? "✓" : String(i+1)}
              </div>
              {!isLast && (
                <div className={`w-0.5 h-8 mt-1 rounded-full ${isDone && !isRefused ? "bg-[#b8d8ef]" : "bg-slate-100"}`}/>
              )}
            </div>
            <div className="pb-4 flex-1">
              <div className={`text-sm font-semibold ${isRefused?"text-[#b5394e]":isDone?"text-slate-800":"text-slate-400"}`}>
                {step.label}
              </div>
              <div className="text-xs text-slate-400 mt-0.5">{step.date}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function StudentApplications() {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("All");
  const [selected, setSelected] = useState(null);

  // 1. جلب البيانات من الـ Backend
  useEffect(() => {
    const fetchApps = async () => {
      try {
        const response = await api.get('applications/');
        setApplications(response.data);
        if (response.data.length > 0) setSelected(response.data[0]);
      } catch (err) {
        console.error("Error fetching applications:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchApps();
  }, []);

  // 2. تصفية البيانات حسب التبويب
  const filtered = tab === "All"
    ? applications
    : applications.filter(a => STATUS_MAP[a.status.toLowerCase()]?.label === tab);

  if (loading) return (
    <StudentLayout active="applications">
      <div className="p-20 text-center animate-pulse text-slate-400">Loading your applications...</div>
    </StudentLayout>
  );

  return (
    <StudentLayout active="applications">
      <div className="p-5 md:p-8">
        {/* Header */}
        <div className="mb-6">
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl">My applications</h1>
          <p className="text-slate-400 text-sm mt-1">Manage and track your internship requests</p>
        </div>
        {/* Tabs */}
        <div className="flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-6">
          {["All", "Pending", "Accepted", "Rejected"].map(t => (
            <button 
              key={t} 
              onClick={() => setTab(t)}
              className={`px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${
                tab === t ? "bg-white text-blue-600 shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              {t}
            </button>
          ))}
        </div>

        <div className="grid md:grid-cols-5 gap-6">
          {/* القائمة اليسرى */}
          <div className="md:col-span-2 space-y-3">
            {filtered.length > 0 ? filtered.map(app => {
              const s = STATUS_MAP[app.status.toLowerCase()] || STATUS_MAP.pending;
              return (
                <div 
                  key={app.id} 
                  onClick={() => setSelected(app)}
                  className={`p-4 rounded-2xl border transition-all cursor-pointer ${
                    selected?.id === app.id ? "border-blue-500 bg-blue-50/30" : "border-slate-200 bg-white hover:border-slate-300"
                  }`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="font-bold text-slate-800 text-sm truncate">{app.offer_details?.title || "Internship"}</h3>
                    <span className={`badge ${s.badge} text-[10px]`}>{s.label}</span>
                  </div>
                  <p className="text-xs text-slate-500 mb-3">{app.offer_details?.company || "Company Name"}</p>
                  <div className="flex justify-between text-[10px] text-slate-400">
                    <span>Applied: {new Date(app.created_at).toLocaleDateString()}</span>
                  </div>
                </div>
              );
            }) : (
              <div className="text-center py-10 bg-slate-50 rounded-2xl border border-dashed">
                <p className="text-sm text-slate-400">No applications found.</p>
              </div>
            )}
          </div>

          {/* تفاصيل الطلب المختار */}
          <div className="md:col-span-3">
            {selected ? (
              <div className="bg-white border border-slate-200 rounded-2xl p-6 sticky top-4">
                <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100">
                  <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-2xl">💼</div>
                  <div>
                    <h2 className="font-syne font-bold text-xl text-slate-900">{selected.offer_details?.title}</h2>
                    <p className="text-slate-500">{selected.offer_details?.company}</p>
                  </div>
                </div>

                <div className={`p-4 rounded-xl mb-6 flex items-center gap-3 text-sm ${
                  selected.status === 'accepted' ? 'bg-green-50 text-green-700' : 
                  selected.status === 'rejected' ? 'bg-red-50 text-red-700' : 'bg-orange-50 text-orange-700'
                }`}>
                  <span>{STATUS_MAP[selected.status.toLowerCase()]?.icon}</span>
                  {STATUS_MAP[selected.status.toLowerCase()]?.msg}
                </div>

                <div className="mb-8">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Tracking Timeline</h4>
                  <Timeline status={selected.status.toLowerCase()} date={new Date(selected.created_at).toLocaleDateString()} />
                </div>

                {selected.status === "accepted" && (
                  <button className="w-full bg-[#2E7DF7] text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                  📄 Download Internship Agreement
                  </button>
                )}
              </div>
            ) : (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Select an application to see details
              </div>
            )}
          </div>
        </div>
      </div>
    </StudentLayout>
  );
}
